/* --- chips (sentence cloze) and proof (two-column builder): blanks filled from a bank --- */
function blanksOf(q){return q.type==='chips'?q.ans.map(function(i){return q.bank[i]}):q.rows.reduce(function(a,r,ri){q.hide[ri].forEach(function(c){a.push(r[c])});return a},[])}
