 for(v=Math.ceil(g.x[0]/sx-1e-9)*sx;v<=g.x[1]+1e-9;v+=sx)s+='<path d="M'+X(v)+' '+T+'V'+(T+ph)+'" stroke-opacity=".13" stroke-width="1"/>'+itT(X(v),T+ph+14,grF(v),10);
