 s+='<path d="M'+L+' '+T+'V'+(T+ph)+'H'+(L+pw)+'" stroke-width="2"/>'+itT(L+pw/2,H-4,esc(g.xl||''),11)+'<text transform="translate(11 '+(T+ph/2)+') rotate(-90)" text-anchor="middle" font-size="11" font-weight="700" fill="currentColor" stroke="none">'+esc(g.yl||'')+'</text>';
 (g.hl||[]).forEach(function(h){if(h.y!==undefined)s+='<path d="M'+L+' '+Y(h.y)+'H'+(L+pw)+'" stroke-dasharray="5 4" stroke-opacity=".7" stroke-width="1.5"/>'+itT(L+pw-2,Y(h.y)-4,esc(h.l||''),10,'end');if(h.x!==undefined)s+='<path d="M'+X(h.x)+' '+T+'V'+(T+ph)+'" stroke-dasharray="5 4" stroke-opacity=".7" stroke-width="1.5"/>'+itT(X(h.x)+3,T+10,esc(h.l||''),10,'start')});
