 S.ra=((S.ra||'')+(ok?'1':'0')).slice(-20);if(window.sfx){if(ok){var rr=S.ra||'',n=0;while(n<rr.length&&rr[rr.length-1-n]==='1')n++;window.sfx(n>=2?'combo':'ok')}else{window.sfx('comboreset');window.sfx(part?'almost':'no')}}
