var _ss=startSess;startSess=function(o){_ss.apply(this,arguments);if(Z){Z.c0=S.coins;Z.ts=Date.now()}};
function fmtT(ms){var s=Math.round(ms/1000),m=Math.floor(s/60);return m?m+'m '+('0'+s%60).slice(-2)+'s':s+'s'}
var _dr=drawResults;
