  if(rev)h+='<div class="simo">Yours gives <b>'+sg(rd(rtot(rn.R,it.o),2))+' Ω</b>. '+(it.ok?'On target.':'Target was '+sg(rn.T)+' Ω: '+rn.sol.map(function(x){return x==='s'?'series':'parallel'}).join(', ')+'.')+'</div>';
