 bindSl(root,{R:' kΩ',C:' µF'},function(id,v){s[id]=v;restart(false)});chipSet(root,function(n,v){s.mode=v;restart(true)});root.addEventListener('click',function(e){if(e.target.closest('[data-la="rs"]'))restart(false)});
