  for(i=0;i<=4;i++){h+='<text x="'+(L-4)+'" y="'+(Y(im*i/4)+3)+'" text-anchor="end" font-size="8" fill="currentColor">'+fx(im*i/4*1000,0)+'</text>'+'<line x1="'+L+'" x2="'+Rr+'" y1="'+Y(im*i/4)+'" y2="'+Y(im*i/4)+'" stroke="#9aa0b4" opacity=".2"/>'}
